def main():
    root=Path(__file__).resolve().parent
    print('Unpacking and verifying the complete PES manual package locally',flush=True)
    for name,content in FILES.items():
        data=content.encode()
        if hashlib.sha256(data).hexdigest()!=SHA256[name]:
            raise RuntimeError('Bundled checksum mismatch: '+name)
        path=root/name
        if path.exists() and path.read_bytes()!=data:
            raise RuntimeError('Use a fresh temporary directory; existing file differs: '+name)
        path.write_bytes(data)
    if sys.argv[1:]==['--verify-only']:
        spec=importlib.util.spec_from_file_location('pes_runner',root/'run.py')
        runner=importlib.util.module_from_spec(spec)
        spec.loader.exec_module(runner)
        runner.assets(None)
        print('Complete bundled package verified without helper downloads',flush=True)
        return
    if sys.argv[1:] not in ([], ['--debug-crash']):
        raise SystemExit('Supported options: --verify-only or --debug-crash')
    print('Starting preparation; PES will wait for your launch from ES-DE',flush=True)
    os.execv(sys.executable,[sys.executable,str(root/'run.py'),'--manual',*sys.argv[1:]])


if __name__=='__main__':
    main()
